From 901046ef9058f1329a5e7ee9848c1086ee6db47f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:42:34 +0100
Subject: [PATCH] TextFieldContextMenu: Open the menu as its own window

The text menu was drawn inside the field's window, so it was cut off or
covered by other windows. It now opens as a window popup at the click,
except in a QQuickWidget, where Qt's window popups miss the next click.

BUG: 517982
---
 .../private/TextFieldContextMenu.qml          | 25 ++++++++++++++++---
 plugin/CMakeLists.txt                         |  1 +
 plugin/windowutils.cpp                        | 16 ++++++++++++
 plugin/windowutils.h                          | 22 ++++++++++++++++
 4 files changed, 60 insertions(+), 4 deletions(-)
 create mode 100644 plugin/windowutils.cpp
 create mode 100644 plugin/windowutils.h

diff --git a/org.kde.desktop/private/TextFieldContextMenu.qml b/org.kde.desktop/private/TextFieldContextMenu.qml
index a6c5bb6..1293e9b 100644
--- a/org.kde.desktop/private/TextFieldContextMenu.qml
+++ b/org.kde.desktop/private/TextFieldContextMenu.qml
@@ -13,6 +13,7 @@ import QtQuick
 import QtQuick.Templates as T
 import org.kde.desktop as QQC2
 import org.kde.kirigami as Kirigami
+import org.kde.qqc2desktopstyle.private as StylePrivate
 import org.kde.sonnet as Sonnet

 QQC2.Menu {
@@ -38,6 +39,19 @@ QQC2.Menu {

     property var runOnMenuClose: () => {}

+    // On Wayland a window menu opens below its whole parent item, so it opens from this point instead
+    readonly property Item __anchor: Item {
+        width: 1
+        height: 1
+    }
+
+    function __popupAt(target, x, y) {
+        __anchor.parent = target;
+        __anchor.x = x;
+        __anchor.y = y;
+        popup(__anchor, 0, 0);
+    }
+
     function storeCursorAndSelection() {
         restoredCursorPosition = target.cursorPosition;
         restoredSelectionStart = target.selectionStart;
@@ -70,10 +84,8 @@ QQC2.Menu {
                     : [];

                 storeCursorAndSelection();
-                popup(target);
                 // slightly locate context menu away from mouse so no item is selected when menu is opened
-                x += 1
-                y += 1
+                __popupAt(target, handlerPoint.position.x + 1, handlerPoint.position.y + 1);
             }
         } else {
             dismiss();
@@ -87,7 +99,7 @@ QQC2.Menu {
             target.persistentSelection = true; // persist selection when menu is opened
             storeCursorAndSelection();
             const targetCursorRectangle = target.cursorRectangle;
-            popup(target, targetCursorRectangle.right, targetCursorRectangle.bottom);
+            __popupAt(target, targetCursorRectangle.right, targetCursorRectangle.bottom);
         }
     }

@@ -126,6 +138,10 @@ QQC2.Menu {
     }

     modal: true
+    // Window popups don't work well in a QQuickWidget: it forwards mouse events without their device, so the
+    // release that goes to the menu window leaves the text field pressed and it misses the next right-click.
+    // See also QTBUG-150265 and QTBUG-152481.
+    popupType: StylePrivate.WindowUtils.isEmbedded(target?.Window.window ?? null) ? T.Popup.Item : T.Popup.Window

     // deal with whether text should be deselected
     onClosed: {
@@ -133,6 +149,7 @@ QQC2.Menu {
         // this menu is about to open for the same item that might have been
         // reparented to a different popup.
         parent = null;
+        __anchor.parent = null;

         // restore text field's original persistent selection setting
         target.persistentSelection = persistentSelectionSetting
diff --git a/plugin/CMakeLists.txt b/plugin/CMakeLists.txt
index 3b91a0e..522f0f6 100644
--- a/plugin/CMakeLists.txt
+++ b/plugin/CMakeLists.txt
@@ -3,6 +3,7 @@ ecm_add_qml_module(qqc2desktopstyleplugin URI org.kde.qqc2desktopstyle.private G
 target_sources(qqc2desktopstyleplugin PRIVATE
     kquickstyleitem.cpp
     itembranchindicators.cpp
+    windowutils.cpp
 )

 target_link_libraries(qqc2desktopstyleplugin PRIVATE
diff --git a/plugin/windowutils.cpp b/plugin/windowutils.cpp
new file mode 100644
index 0000000..8bfb1de
--- /dev/null
+++ b/plugin/windowutils.cpp
@@ -0,0 +1,16 @@
+/*
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+*/
+
+#include "windowutils.h"
+
+#include <QQuickRenderControl>
+#include <QQuickWindow>
+
+bool WindowUtils::isEmbedded(QQuickWindow *window) const
+{
+    return window && QQuickRenderControl::renderWindowFor(window);
+}
+
+#include "moc_windowutils.cpp"
diff --git a/plugin/windowutils.h b/plugin/windowutils.h
new file mode 100644
index 0000000..a8324af
--- /dev/null
+++ b/plugin/windowutils.h
@@ -0,0 +1,22 @@
+/*
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+*/
+
+#pragma once
+
+#include <QObject>
+#include <QQmlEngine>
+
+class QQuickWindow;
+
+class WindowUtils : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+public:
+    // Whether the window is rendered into another window, as in a QQuickWidget, instead of being shown on its own
+    Q_INVOKABLE bool isEmbedded(QQuickWindow *window) const;
+};
-- 
